    Particle &p = particles[i];

    // Initialize density with self-contribution
    float density = selfDens;

    // Get cell coordinates from hash
    glm::ivec3 cell;
    cell.x = p.hash & 0xFF;
    cell.y = (p.hash >> 8) & 0xFF;
    cell.z = (p.hash >> 16) & 0xFF;

    // Check 27 neighbor cells (3x3x3 grid)
    for (int dx = -1; dx <= 1; ++dx) {
        for (int dy = -1; dy <= 1; ++dy) {
            for (int dz = -1; dz <= 1; ++dz) {
                glm::ivec3 neighborCell = cell + glm::ivec3(dx, dy, dz);

                // Compute hash for neighbor cell
                uint32_t cellHash = (neighborCell.x & 0xFF) | 
                                   ((neighborCell.y & 0xFF) << 8) | 
                                   ((neighborCell.z & 0xFF) << 16);

                // Find particles in this cell
                for (size_t j = particleTable[cellHash]; j < particleCount; ++j) {
                    if (particles[j].hash != cellHash) break;

                    glm::vec3 rVec = p.position - particles[j].position;
                    float r2 = glm::dot(rVec, rVec);

                    if (r2 < h2 && r2 > 0.0f) {
                        float diff = h2 - r2;
                        density += mass * poly6 * diff * diff * diff;
                    }
                }
            }
        }
    }

    p.density = density;
    p.pressure = gasConstant * (density - restDensity);
